Provides REST endpoints to retrieve blockchain data from the Bitcoin network.
"""

import json
import socket
import struct
import hashlib
import time
from flask import Flask, jsonify, abort
from bitcoinlib.services.services import Service
from bitcoinlib.networks import Network
from bitcoinlib.encoding import to_hexstring, addr_to_pubkeyhash
import requests

app = Flask(__name__)

class BitcoinNetworkClient:
    """Bitcoin network client to connect and fetch blockchain data"""

    def __init__(self):
        self.host = '127.0.0.1'
        self.port = 8333
        self.network = 'bitcoin'

    def connect_to_node(self):
        """Attempt to connect to a Bitcoin node"""
        try:
            # Try to connect to local Bitcoin Core node
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            result = sock.connect_ex((self.host, self.port))
            sock.close()
            return result == 0
        except Exception:
            return False

    def get_block_by_hash(self, block_hash):
        """Get block details by hash using bitcoinlib service"""
        try:
            # Use bitcoinlib service to fetch block data
            service = Service(network=self.network)
            block_data = service.getblock(block_hash)

            if not block_data:
                return None

            # Format response according to schema
            response = {
                "hash": block_data.get('hash', block_hash),
                "height": block_data.get('height', 0),
                "merkleroot": block_data.get('merkleroot', ''),
                "time": block_data.get('time', int(time.time())),
                "nonce": block_data.get('nonce', 0),
                "tx": block_data.get('tx', [])
            }
            return response

        except Exception as e:
            print(f"Error fetching block {block_hash}: {e}")
            return None

    def get_transaction_by_id(self, txid):
        """Get transaction details by transaction ID"""
        try:
            service = Service(network=self.network)
            tx_data = service.gettransaction(txid)

            if not tx_data:
                return None

            # Format response according to schema
            response = {
                "txid": tx_data.get('txid', txid),
                "blockhash": tx_data.get('blockhash', ''),
                "vin": [],
                "vout": []
            }

            # Process inputs
            if 'vin' in tx_data:
                for vin in tx_data['vin']:
                    input_data = {
                        "coinbase": vin.get('coinbase', ''),
                        "sequence": vin.get('sequence', 0)
                    }
                    response['vin'].append(input_data)

            # Process outputs
            if 'vout' in tx_data:
                for vout in tx_data['vout']:
                    script_pub_key = vout.get('scriptPubKey', {})
                    output_data = {
                        "value": vout.get('value', 0),
                        "n": vout.get('n', 0),
                        "scriptPubKey": {
                            "asm": script_pub_key.get('asm', ''),
                            "hex": script_pub_key.get('hex', ''),
                            "type": script_pub_key.get('type', '')
                        }
                    }
                    response['vout'].append(output_data)

            return response

        except Exception as e:
            print(f"Error fetching transaction {txid}: {e}")
            return None

    def get_network_status(self):
        """Get network connectivity status"""
        try:
            # Check if we can connect to Bitcoin network
            if self.connect_to_node():
                return {"status": "online"}
            else:
                # Try alternative method using bitcoinlib
                service = Service(network=self.network)
                # Try to get latest block as connectivity test
                latest_block = service.blockcount()
                if latest_block:
                    return {"status": "online"}
                else:
                    return {"status": "connection failed - no Bitcoin node available"}
        except Exception as e:
            return {"status": f"connection failed - {str(e)}"}

