@app.route('/block/<block_hash>', methods=['GET'])
def get_block(block_hash):
    """Get block details by hash"""
    try:
        # Validate block hash format (should be 64 character hex string)
        if len(block_hash) != 64 or not all(c in '0123456789abcdefABCDEF' for c in block_hash):
            abort(404, description="Invalid block hash format")

        block_data = bitcoin_client.get_block_by_hash(block_hash)

        if block_data is None:
            abort(404, description="Block not found")

        return jsonify(block_data)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

