    try:
        # Validate transaction ID format (should be 64 character hex string)
        if len(txid) != 64 or not all(c in '0123456789abcdefABCDEF' for c in txid):
            abort(404, description="Invalid transaction ID format")

        tx_data = bitcoin_client.get_transaction_by_id(txid)

        if tx_data is None:
            abort(404, description="Transaction not found")

        return jsonify(tx_data)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

