class BitcoinRequestHandler(http.server.BaseHTTPRequestHandler):
    """HTTP request handler for Bitcoin API"""

    def do_GET(self):
        """Handle GET requests"""
        try:
            parsed_url = urlparse(self.path)
            path = parsed_url.path

            # Route handling
            if path.startswith('/block/'):
                block_hash = path.split('/block/')[1]
                self.handle_get_block(block_hash)
            elif path.startswith('/transaction/'):
                txid = path.split('/transaction/')[1]
                self.handle_get_transaction(txid)
            elif path == '/status':
                self.handle_get_status()
            else:
                self.send_error_response(404, "Endpoint not found")

        except Exception as e:
            self.send_error_response(500, str(e))

    def handle_get_block(self, block_hash):
        """Handle block endpoint"""
        try:
            # Validate block hash format
            if len(block_hash) != 64 or not all(c in '0123456789abcdefABCDEF' for c in block_hash):
                self.send_error_response(404, "Invalid block hash format")
                return

            block_data = bitcoin_api.get_block_by_hash(block_hash)

            if block_data is None:
                self.send_error_response(404, "Block not found")
                return

            self.send_json_response(block_data)

        except Exception as e:
            self.send_error_response(500, str(e))

    def handle_get_transaction(self, txid):
        """Handle transaction endpoint"""
        try:
            # Validate transaction ID format
            if len(txid) != 64 or not all(c in '0123456789abcdefABCDEF' for c in txid):
                self.send_error_response(404, "Invalid transaction ID format")
                return

            tx_data = bitcoin_api.get_transaction_by_id(txid)

            if tx_data is None:
                self.send_error_response(404, "Transaction not found")
                return

            self.send_json_response(tx_data)

        except Exception as e:
            self.send_error_response(500, str(e))

    def handle_get_status(self):
        """Handle status endpoint"""
        try:
            status = bitcoin_api.get_network_status()
            self.send_json_response(status)

        except Exception as e:
            self.send_error_response(500, str(e))

    def send_json_response(self, data):
        """Send JSON response"""
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        json_data = json.dumps(data).encode('utf-8')
        self.wfile.write(json_data)

    def send_error_response(self, status_code, message):
        """Send error response"""
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        error_data = {"error": message}
        json_data = json.dumps(error_data).encode('utf-8')
        self.wfile.write(json_data)

    def log_message(self, format, *args):
        """Override to customize logging"""
        print(f"{self.address_string()} - {format % args}")

